--     131, 132 and 133 are NOT recorded: Render's tracking table does not match the repository's history.
INSERT INTO migrations (name) SELECT unnest(ARRAY['20261115_01_notification_and_audit_tables.sql', '20261115_02_backfill_primary_business.sql', '20261115_03_stripe_entitlement.sql', '20261115_04_invoice_period_unique_for_internal_only.sql', '20261117_01_login_throttle.sql']::text[]);
COMMIT;
\echo 'MIGRATION COMMITTED. Next: run 2026-11-18_phase1_render_verify.sql and check its exit code is 0.'
